// Remove zero-width spaces and other invisible characters from a string
function sanitizeString(str) {
    if (!str || typeof str !== 'string') return str;
    // Remove zero-width space, zero-width non-joiner, zero-width joiner, and other invisible characters
    return str.replace(/[\u200B-\u200D\uFEFF]/g, '');
}

// Sanitize only string values in an object while preserving structure
function sanitizeInvoiceData(invoice) {
    // Create a deep copy using JSON parse/stringify
    const sanitized = JSON.parse(JSON.stringify(invoice));

    // Recursively sanitize all string values
    function sanitizeValue(obj) {
        if (typeof obj === 'string') {
            return sanitizeString(obj);
        }
        if (Array.isArray(obj)) {
            return obj.map(sanitizeValue);
        }
        if (obj && typeof obj === 'object') {
            const result = {};
            for (const key in obj) {
                result[key] = sanitizeValue(obj[key]);
            }
            return result;
        }
        return obj;
    }

    return sanitizeValue(sanitized);
}

